import json


async def app(scope, receive, send):
    if scope["type"] != "http":
        return
    if scope["method"] == "GET" and scope["path"] == "/healthz":
        status, body, kind = 200, json.dumps({"status": "ok"}).encode(), b"application/json"
    else:
        status, body, kind = 404, b"Not Found", b"text/plain"
    await send({
        "type": "http.response.start",
        "status": status,
        "headers": [(b"content-type", kind), (b"content-length", str(len(body)).encode())],
    })
    await send({"type": "http.response.body", "body": body})

