import asyncio
import time

from fastapi import FastAPI

app = FastAPI()


@app.get("/healthz")
async def healthz() -> dict[str, str]:
    return {"status": "ok"}


@app.get("/blocking")
async def blocking() -> dict[str, bool]:
    time.sleep(2)
    return {"done": True}


@app.get("/waiting")
async def waiting() -> dict[str, bool]:
    await asyncio.sleep(2)
    return {"done": True}


@app.get("/threaded")
def threaded() -> dict[str, bool]:
    time.sleep(2)
    return {"done": True}
